package com.ruoyi.web.controller.shop;
import java.util.*;import java.io.*;import java.math.BigDecimal;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.transaction.annotation.Transactional;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;import com.alibaba.fastjson2.*;import com.ruoyi.common.core.domain.AjaxResult;import com.ruoyi.common.utils.SecurityUtils;import static com.ruoyi.web.controller.shop.ShopService.*;
@RestController @RequestMapping("/shop/admin/catalog") @PreAuthorize("@ss.hasAnyPermi('shop:manage,shop:catalog')") public class ShopCatalogController {
 @Autowired ShopService s;@Autowired ShopAdminController products;
 private String who(){return SecurityUtils.getUsername();}
 @GetMapping public AjaxResult config(){JSONObject config=s.rules();config.put("series",s.productSeries());return AjaxResult.success(config);}
 @PostMapping("/settings") @Transactional public AjaxResult settings(@RequestBody JSONObject b){s.one("select content from shop_config where config_key='product_series' for update");if(b.containsKey("series")){JSONArray series=b.getJSONArray("series");check(series!=null&&series.size()<=100,"产品系列最多100个");Set<String> seen=new HashSet<>();for(int i=0;i<series.size();i++){String name=str(series.get(i)).trim();check(!name.isEmpty()&&name.length()<=60&&!Arrays.asList("全部系列","未分系列").contains(name)&&seen.add(name),"系列名称需1至60字，不能重复或使用全部系列、未分系列");series.set(i,name);}for(Map<String,Object> p:s.jdbc().queryForList("select distinct series from shop_product where archived=0 and series<>''"))check(series.contains(p.get("series")),"仍有商品使用系列“"+p.get("series")+"”，请先修改商品所属系列");s.jdbc().update("update shop_config set content=? where config_key='product_series'",series.toJSONString());}JSONArray categories=b.getJSONArray("categories"),brands=b.getJSONArray("brands");check(categories!=null&&!categories.isEmpty()&&categories.size()<=100&&brands!=null&&brands.size()<=300,"请填写分类和品牌列表");for(JSONArray list:Arrays.asList(categories,brands)){Set<String> seen=new HashSet<>();for(Object x:list){String name=str(x).trim();check(name.length()>0&&name.length()<=(list==categories?40:60)&&seen.add(name),"分类最多40字、品牌最多60字，不能为空或重复");}}for(Map<String,Object> p:s.jdbc().queryForList("select distinct category from shop_product where archived=0"))check(categories.contains(p.get("category")),"仍有商品使用分类“"+p.get("category")+"”，请先修改商品分类");s.one("select content from shop_config where config_key='rules' for update");JSONObject rules=s.rules();rules.put("categories",categories);rules.put("brands",brands);s.jdbc().update("update shop_config set content=? where config_key='rules'",rules.toJSONString());s.event("catalog",0,"更新分类、品牌、系列及展示顺序",who());return AjaxResult.success();}
 @PostMapping("/batch") @Transactional public AjaxResult batch(@RequestBody JSONObject b){JSONArray ids=b.getJSONArray("ids");check(ids!=null&&!ids.isEmpty()&&ids.size()<=500,"请选择1至500个商品");String action=str(b.get("action"));check(Arrays.asList("enable","disable","retailOn","retailOff","wholesaleOn","wholesaleOff","archive").contains(action),"请选择批量操作");String field=action.startsWith("retail")?"retail_enabled":action.startsWith("wholesale")?"wholesale_enabled":"enabled";boolean enabled=Arrays.asList("enable","retailOn","wholesaleOn").contains(action);SortedSet<Long> sorted=new TreeSet<>();for(Object id:ids)sorted.add(integer(id,1,Long.MAX_VALUE,"商品编号不正确"));for(long id:sorted){Map<String,Object> product=s.one("select id,archived from shop_product where id=? for update",id);if("archive".equals(action)){if(number(product.get("archived"))==0){s.jdbc().update("update shop_product set archived=1,enabled=0,version=version+1 where id=?",id);s.event("product",id,"删除商品（保留历史订单和库存记录）",who());}}else{check(number(product.get("archived"))==0,"商品已删除，请刷新列表");s.jdbc().update("update shop_product set "+field+"=?,version=version+1 where id=?",enabled,id);s.event("product",id,"批量"+action,who());}}return AjaxResult.success();}
 private static final String[] HEAD={"是否导入（填是）","商品编码（新建留空）","商品名称","分类","品牌","规格","零售价（元）","采购价（元）","采购倍数","主图路径","新建库存（件）","上架（是或否）","零售开放（是或否）","采购开放（是或否）","介绍","产品系列（可选）"};
 @GetMapping("/template") public ResponseEntity<byte[]> template()throws IOException{try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet sh=wb.createSheet("商品导入");Row head=sh.createRow(0);for(int n=0;n<HEAD.length;n++)head.createCell(n).setCellValue(HEAD[n]);int row=1;for(Map<String,Object> p:s.jdbc().queryForList("select * from shop_product where archived=0 order by id limit 10000")){Row r=sh.createRow(row++);Object[] vals={"",p.get("product_code"),p.get("name"),p.get("category"),p.get("brand"),p.get("spec"),number(p.get("price"))/100.0,number(p.get("wholesale"))/100.0,p.get("pack"),p.get("image"),0,yes(p.get("enabled")),yes(p.get("retail_enabled")),yes(p.get("wholesale_enabled")),p.get("detail"),p.get("series")};for(int n=0;n<vals.length;n++){if(vals[n] instanceof Number)r.createCell(n).setCellValue(((Number)vals[n]).doubleValue());else r.createCell(n).setCellValue(str(vals[n]));}}for(int n=0;n<HEAD.length;n++)sh.setColumnWidth(n,(n==2||n==9||n==14?38:22)*256);sh.createFreezePane(0,1);Sheet notes=wb.createSheet("填写说明");notes.createRow(0).createCell(0).setCellValue("仅导入第一列填“是”的行。修改已有商品保留编码；新建商品可填未使用的编码或留空自动生成，主图先在商品管理上传后填写其路径。现有商品库存不会被覆盖。请填写数值，不使用公式。最多500条。");notes.setColumnWidth(0,100*256);wb.write(out);return ResponseEntity.ok().cacheControl(CacheControl.noStore()).header("Content-Disposition","attachment; filename=catalog.xlsx").contentType(MediaType.parseMediaType("application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")).body(out.toByteArray());}}
 private String yes(Object v){return Boolean.TRUE.equals(v)||"1".equals(str(v))?"是":"否";}
 private String cell(Row r,int n){Cell c=r.getCell(n);if(c==null)return "";check(c.getCellType()!=CellType.FORMULA,"不要使用公式");return c.getCellType()==CellType.NUMERIC?BigDecimal.valueOf(c.getNumericCellValue()).stripTrailingZeros().toPlainString():new DataFormatter().formatCellValue(c).trim();}
 private boolean flag(String text){check("是".equals(text)||"否".equals(text),"上架及渠道开关请填是或否");return "是".equals(text);}
 private long money(String text){try{long value=new BigDecimal(text).movePointRight(2).longValueExact();return integer(value,1,100000000,"金额应为0.01至1000000元");}catch(Exception e){throw new IllegalArgumentException("金额最多两位小数且大于0");}}
 @PostMapping("/preview") @Transactional public AjaxResult preview(@RequestParam("file") MultipartFile file)throws IOException{check(file.getSize()>0&&file.getSize()<=5*1024*1024,"请上传5MB以内的xlsx商品表");JSONArray rows=new JSONArray(),errors=new JSONArray();Set<Long> ids=new HashSet<>();Set<String> codes=new HashSet<>();try(XSSFWorkbook wb=new XSSFWorkbook(file.getInputStream())){Sheet sh=wb.getSheetAt(0);check(sh.getLastRowNum()<=10000&&sh.getRow(0)!=null,"表格最多10000行");for(int n=0;n<HEAD.length;n++)check((n==15&&cell(sh.getRow(0),n).isEmpty())||HEAD[n].equals(cell(sh.getRow(0),n))||(n==1&&"商品编号（新建留空）".equals(cell(sh.getRow(0),n))),"请使用商品导入模板，保留原列标题");for(int n=1;n<=sh.getLastRowNum();n++){Row row=sh.getRow(n);if(row==null)continue;try{String selected=cell(row,0);if(selected.isEmpty()||"否".equals(selected))continue;check("是".equals(selected),"第一列填是或留空");check(rows.size()<500,"每次最多导入500条");String idText=cell(row,1);check(idText.isEmpty()||codes.add(idText.toUpperCase(java.util.Locale.ROOT)),"同一商品编码不能重复");boolean legacy="商品编号（新建留空）".equals(cell(sh.getRow(0),1));long id=0;if(!idText.isEmpty()){if(legacy)id=integer(idText,1,Long.MAX_VALUE,"商品编号不正确");else{List<Map<String,Object>> matched=s.jdbc().queryForList("select id from shop_product where product_code=?",idText);if(!matched.isEmpty())id=number(matched.get(0).get("id"));check(idText.toUpperCase(java.util.Locale.ROOT).matches("[A-Z0-9][A-Z0-9_.-]{0,59}"),"商品编码格式不正确");}}check(id==0||ids.add(id),"同一商品编号不能重复");JSONObject b=id==0?new JSONObject():new JSONObject(s.one("select * from shop_product where id=?",id));check(number(b.get("archived"))==0,"商品已删除，请新建商品并使用新的商品编码");b.put("id",id);if(!legacy)b.put("productCode",idText);b.put("name",cell(row,2));b.put("category",cell(row,3));b.put("brand",cell(row,4));b.put("spec",cell(row,5));b.put("price",money(cell(row,6)));b.put("wholesale",money(cell(row,7)));b.put("pack",integer(cell(row,8),1,10000,"采购倍数须为正整数"));b.put("image",cell(row,9));if(id==0){b.put("stock",integer(cell(row,10).isEmpty()?"0":cell(row,10),0,100000000,"初始库存不正确"));b.put("family_id",0);b.put("gallery",new JSONArray());}else b.put("gallery",JSON.parseArray(str(b.get("gallery"))));b.put("enabled",flag(cell(row,11)));b.put("retail_enabled",flag(cell(row,12)));b.put("wholesale_enabled",flag(cell(row,13)));b.put("detail",cell(row,14));if(HEAD[15].equals(cell(sh.getRow(0),15))){String series=cell(row,15);check(series.isEmpty()||s.productSeries().contains(series),"系列不存在，请先在系列设置中添加");b.put("series",series);}check(str(b.get("name")).length()>=2&&str(b.get("name")).length()<=120,"名称须为2至120字");check(s.rules().getJSONArray("categories").contains(b.getString("category")),"分类不存在，请先在分类设置中添加");check(str(b.get("brand")).length()<=60&&str(b.get("spec")).length()>0&&str(b.get("spec")).length()<=60,"品牌或规格长度不正确");check(str(b.get("image")).startsWith("/")&&!str(b.get("image")).startsWith("//"),"请填写已上传的主图路径");b.put("sheetRow",n+1);rows.add(b);}catch(IllegalArgumentException e){errors.add("第"+(n+1)+"行："+e.getMessage());}if(errors.size()>=100)break;}}
 JSONObject result=new JSONObject();result.put("rows",rows);result.put("errors",errors);if(errors.isEmpty()&&!rows.isEmpty()){String ticket=UUID.randomUUID().toString();s.jdbc().update("insert into shop_catalog_import(ticket,owner_name,rows_json,expires_at) values(?,?,?,date_add(now(),interval 30 minute))",ticket,who(),rows.toJSONString());result.put("ticket",ticket);}s.jdbc().update("delete from shop_catalog_import where expires_at<date_sub(now(),interval 1 day)");return AjaxResult.success(result);}
 @PostMapping("/commit") @Transactional public AjaxResult commit(@RequestBody JSONObject b){Map<String,Object> job=s.one("select * from shop_catalog_import where ticket=? and owner_name=? for update",str(b.get("ticket")),who());if("done".equals(job.get("status")))return AjaxResult.success(JSON.parseArray(str(job.get("result_json"))));check(timestamp(job.get("expires_at")).getTime()>System.currentTimeMillis(),"预览已超过30分钟，请重新上传确认");JSONArray ids=new JSONArray();for(Object obj:JSON.parseArray(str(job.get("rows_json")))){JSONObject item=JSON.parseObject(JSON.toJSONString(obj));products.product(item);ids.add(item.getLongValue("id"));}s.jdbc().update("update shop_catalog_import set status='done',result_json=? where ticket=?",ids.toJSONString(),job.get("ticket"));s.event("catalog",0,"确认导入"+ids.size()+"个商品",who());return AjaxResult.success(ids);}
}
